// A zone and a locale the load names itself: the same on every machine.
var instant = new Date(1577836800000);
module.exports = {
  parsed: Date.parse("2020-01-01T00:00:00Z") + Date.parse("2020-01-01") + Date.parse("2020-01-01T02:00:00+02:00"),
  iso: instant.toISOString(),
  hour: instant.getUTCHours(),
  text: instant.toLocaleString("en-US", { timeZone: "UTC" }),
  number: (1234.5).toLocaleString("de-DE"),
  order: "\u00e4".localeCompare("z", "sv"),
};
